={
  "messaging_product": "whatsapp",
  "to": "={{$json["messages"][0]["from"]}}",
  "type": "interactive",
  "interactive": {
    "type": "button",
    "body": {
      "text": "Ciao! Cosa vorresti fare con le prenotazioni?"
    },
    "action": {
      "buttons": [
        {
          "type": "reply",
          "reply": {
            "id": "crea",
            "title": "Crea una nuova"
          }
        },
        {
          "type": "reply",
          "reply": {
            "id": "visualizza",
            "title": "Visualizza"
          }
        }
      ]
    }
  }
}

={
  "messaging_product": "whatsapp",
  "to": "={{ $('WhatsApp Trigger').item.json.contacts[0].wa_id }}",
  "type": "interactive",
  "interactive": {
    "type": "list",
    "body": {
      "text": "Ecco le tue prenotazioni!"
    },
    "action": {
      "button": "Le tue prenotazioni",
      "sections": [
        {
          "title": "Le tue prenotazioni",
          "rows": {{ JSON.stringify($fromAI('rows', 'the output of Raccogli eventi utente must be formatted as rows with id and title for the WhatsApp interactive list template. The id should be u_[date_time]. In addition to the list of events, you must ALWAYS include exactly one additional button: id=menu_principale and title=Menu principale. This option must ALWAYS be present, even if the list of events is empty or contains only one item','json')) }}
        }
      ]
    }
  }
}

={
  "messaging_product": "whatsapp",
  "to": "={{ $('WhatsApp Trigger').item.json.contacts[0].wa_id }}",
  "type": "interactive",
