    "type": "list",
    "body": {
      "text": "Ore disponibili il {{ $fromAI('date','format: DD/MM/YYYY') }}"
    },
    "action": {
      "button": "Scegli un'ora:",
      "sections": [
        {
          "title": "Ore disponibili",
